import math
import random
import time

import lib


# ----------------------------------------------------------------------------
# Strategy.
#
# Bi-Cayley lifts over groups that are NOT restricted to semidirect products of
# cyclic groups. Two group sources are mixed:
#   1. Semidirect products Z_m x|_r Z_k (cheap, exact orders).
#   2. Permutation groups generated by two sparse random permutations, kept only
#      when the closure has order in [target, cap]. These give many small
#      non-metacyclic groups, e.g. PSL(2,7) of order 168 when it appears.
#
# Vertices A_x, B_y for x, y in G with A_x ~ B_{x s} for s in S, |S| = d and
# the identity in S. Left multiplication is an automorphism, so the diameter
# check only needs BFS from A_e and B_e. A simulated-annealing search over S
# minimises the number of unreached pairs.
#
# Safe fallback: K_{d,d} (valid for every D >= 2). Every candidate is checked
# with lib.is_valid before it replaces the current best.
# ----------------------------------------------------------------------------

_BFS_MAX_ITERS = 600


def _best_pg(d):
    """Incidence graph of PG(2, q) for the largest prime power q with q + 1 <= d."""
    for q in range(d - 1, 1, -1):
        if lib.is_prime_power(q):
            return lib.projective_plane_incidence(q)
    return None


# ----------------------------------------------------------------------------
# Group sources. Each returns (N, T, invs) with identity index 0,
# T[x][g] = x*g and invs[g] = g^-1.
# ----------------------------------------------------------------------------

def _semidirect_candidate(target, rng):
    """Random semidirect product Z_m x|_r Z_k with order in [target, target + 12)."""
    opts = []
    for N in range(target, target + 12):
        for k in range(1, N + 1):
            if N % k:
                continue
            m = N // k
            for r in range(m):
                if math.gcd(r, m) == 1 and pow(r, k, m) == 1 % m:
                    opts.append((m, k, r))
    if not opts:
        return None
    m, k, r = rng.choice(opts)
    order, mul, inv = lib.semidirect_group(m, k, r)
    T = [[mul(x, g) for g in range(order)] for x in range(order)]
    invs = [inv(g) for g in range(order)]
    return order, T, invs


def _sparse_perm(n, rng):
    """Random permutation of n points made of disjoint cycles of length <= 6."""
    pts = list(range(n))
    rng.shuffle(pts)
    p = list(range(n))
    i = 0
    while i < n:
        L = rng.randint(1, min(6, n - i))
        cyc = pts[i:i + L]
        for a in range(L):
            p[cyc[a]] = cyc[(a + 1) % L]
        i += L
    return tuple(p)


def _closure(gens, n, cap):
    """Permutation group generated by gens, as (elems, idx) with identity at 0; None if order > cap."""
    ident = tuple(range(n))
    elems = [ident]
    idx = {ident: 0}
    i = 0
    while i < len(elems):
        x = elems[i]
        i += 1
        for g in gens:
            y = tuple(x[j] for j in g)
            if y not in idx:
                if len(elems) >= cap:
                    return None
                idx[y] = len(elems)
                elems.append(y)
    return elems, idx


def _perm_table(elems, idx):
    """Multiplication table T[x][g] = x o g and inverse table for a permutation group."""
    n = len(elems[0])
    T = []
    for x in elems:
        T.append([idx[tuple(x[j] for j in g)] for g in elems])
    invs = []
    for g in elems:
        inv = [0] * n
        for k, v in enumerate(g):
            inv[v] = k
        invs.append(idx[tuple(inv)])
    return T, invs


def _perm_candidate(target, cap_order, rng, deadline):
    """Random permutation group with order in [target, min(cap_order, 2*target + 20)]."""
    cap = min(cap_order, 2 * target + 20)
    if cap < target:
        return None
    while time.monotonic() < deadline:
        n = rng.randint(6, 12)
        gens = [_sparse_perm(n, rng), _sparse_perm(n, rng)]
        res = _closure(gens, n, cap)
        if res is None:
            continue
        elems, idx = res
        N = len(elems)
        if N < target:
            continue
        T, invs = _perm_table(elems, idx)
        return N, T, invs
    return None


# ----------------------------------------------------------------------------
# Bi-Cayley search.
# ----------------------------------------------------------------------------

def _unreached(N, T, invs, S, D):
    """Count (source, target) pairs not within distance D, from A_e and B_e."""
    Sinv = [invs[g] for g in S]
    total = 0
    for src in (0, N):
        seen = bytearray(2 * N)
        seen[src] = 1
        count = 1
        frontier = [src]
        for _ in range(D):
            nxt = []
            for u in frontier:
                if u < N:
                    row = T[u]
                    for g in S:
                        v = N + row[g]
                        if not seen[v]:
                            seen[v] = 1
                            nxt.append(v)
                else:
                    row = T[u - N]
                    for h in Sinv:
                        v = row[h]
                        if not seen[v]:
                            seen[v] = 1
                            nxt.append(v)
            count += len(nxt)
            frontier = nxt
            if not frontier:
                break
        total += 2 * N - count
    return total


def _anneal(N, T, invs, d, D, rng, deadline):
    """Anneal connection sets (identity fixed in S) until zero unreached pairs or deadline."""
    while time.monotonic() < deadline:
        S = [0] + rng.sample(range(1, N), d - 1)
        cur = _unreached(N, T, invs, S, D)
        temp = 1.0
        for it in range(_BFS_MAX_ITERS):
            if cur == 0:
                return S
            if (it & 15) == 0 and time.monotonic() > deadline:
                break
            i = rng.randrange(1, d)
            c = rng.randrange(1, N)
            if c in S:
                continue
            S2 = S[:]
            S2[i] = c
            v = _unreached(N, T, invs, S2, D)
            if v <= cur or rng.random() < math.exp(-(v - cur) / temp):
                S, cur = S2, v
            temp = max(0.2, temp * 0.995)
        if cur == 0:
            return S
    return None


# ----------------------------------------------------------------------------
# Main entry point.
# ----------------------------------------------------------------------------

def build(d, D, seed, time_limit):
    start = time.monotonic()
    budget = max(0.5, min(0.85 * time_limit, time_limit - 4.0))
    deadline = start + budget
    rng = random.Random(seed)

    if d < 1 or D < 1:
        return 1, []
    if D == 1:
        return 2, [(0, 1)]

    # Safe fallback: K_{d,d}, diameter 2, valid for every D >= 2.
    best = lib.haar_graph(d, range(d))
    if D == 2:
        return best

    moore = lib.moore_bound(d, D)

    def consider(n, e):
        nonlocal best
        if n > best[0] and lib.is_valid(n, e, d, D):
            best = (n, e)

    if D == 3:
        pg = _best_pg(d)
        if pg is not None:
            consider(pg[0], pg[1])

    # Main search: bi-Cayley lifts over mixed group sources, aiming above best.
    while best[0] < moore and time.monotonic() < deadline:
        target = best[0] // 2 + 1
        if target > moore // 2:
            break
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            break
        slice_end = time.monotonic() + min(remaining, 6.0)

        grp = None
        if rng.random() < 0.4:
            grp = _semidirect_candidate(target, rng)
        if grp is None:
            grp = _perm_candidate(target, moore // 2, rng, deadline)
        if grp is None:
            continue

        N, T, invs = grp
        if N < d:
            continue
        S = _anneal(N, T, invs, d, D, rng, min(slice_end, deadline))
        if S is not None:
            edges = [(x, N + T[x][g]) for x in range(N) for g in S]
            consider(2 * N, edges)

    if not lib.is_valid(best[0], best[1], d, D):
        best = lib.haar_graph(d, range(d))
    return best
